package com.streamcraft.core.runtime;
import java.io.*; import java.util.*; import org.apache.flink.core.io.SimpleVersionedSerializer;
final class HdfsFileEnumeratorStateSerializer implements SimpleVersionedSerializer<HdfsFileEnumeratorState>{private static final int VERSION=1;private final HdfsFileSourceSplitSerializer ss=new HdfsFileSourceSplitSerializer();public int getVersion(){return VERSION;}public byte[] serialize(HdfsFileEnumeratorState s)throws IOException{ByteArrayOutputStream b=new ByteArrayOutputStream();try(DataOutputStream o=new DataOutputStream(b)){o.writeByte(VERSION);List<HdfsFileSourceSplit> p=s==null?List.of():s.pendingSplits();o.writeInt(p.size());for(HdfsFileSourceSplit x:p){byte[]z=ss.serialize(x);o.writeInt(z.length);o.write(z);}List<String> k=s==null?List.of():s.knownSplitIds().stream().sorted().toList();o.writeInt(k.size());for(String x:k){byte[]z=x.getBytes(java.nio.charset.StandardCharsets.UTF_8);o.writeInt(z.length);o.write(z);}}return b.toByteArray();}public HdfsFileEnumeratorState deserialize(int v,byte[]d)throws IOException{if(v!=VERSION||d==null)throw new IOException("Invalid HDFS enumerator state.");try(DataInputStream i=new DataInputStream(new ByteArrayInputStream(d))){if(i.readUnsignedByte()!=VERSION)throw new IOException("Invalid HDFS enumerator marker.");int n=i.readInt();if(n<0||n>i.available())throw new IOException("Invalid HDFS split count.");List<HdfsFileSourceSplit>p=new ArrayList<>();for(int k=0;k<n;k++){int z=i.readInt();if(z<0||z>i.available())throw new IOException("Invalid HDFS split length.");byte[]x=i.readNBytes(z);if(x.length!=z)throw new IOException("Truncated HDFS split.");p.add(ss.deserialize(1,x));}int m=i.readInt();if(m<0||m>i.available())throw new IOException("Invalid HDFS known count.");Set<String> known=new LinkedHashSet<>();for(int k=0;k<m;k++)known.add(IncrementalSourceStateSerializerSupport.readString(i,"HDFS known split id"));if(i.available()!=0)throw new IOException("Trailing bytes in HDFS enumerator state.");return new HdfsFileEnumeratorState(p,known);}}
}
